/** Load licensed Jolpica data from GitHub Pages snapshots generated by Actions. */
const SEASON_RESOURCES = new Set(['races','driverstandings','constructorstandings']);
export async function getSeasonData(api, resource, year, {
  refresh=false, fetcher=globalThis.fetch,
  baseUrl=typeof location === 'undefined'
    ? 'https://mukasanches.github.io/APEXIUM/' : location.href,
}={}) {
  if (!SEASON_RESOURCES.has(resource)) throw new RangeError('Recurso sazonal inválido');
  if (!Number.isInteger(Number(year)) || Number(year)<1950 || Number(year)>2100) {
    throw new RangeError('Temporada inválida');
  }
  const preloaded = !refresh && typeof document !== 'undefined'
    ? document.getElementById('apexium-preloaded') : null;
  if (preloaded) {
    try {
      const bundle = JSON.parse(preloaded.textContent);
      const data = bundle?.[String(year)]?.[resource];
      if (data?.schema === 'apexium-jolpica-snapshot-v1' &&
          Number(data.year) === Number(year) && data.resource === resource &&
          Array.isArray(data.rows) && data.rows.length > 0 &&
          /^https:\/\/api\.jolpi\.ca\//.test(data.url)) {
        return {rows:data.rows,source:'jolpica',url:data.url,
          fetchedAt:data.fetchedAt,cached:true,
          metadata:{...data.metadata,via:'apexium-embedded-snapshot'}};
      }
    } catch (error) {
      // An invalid bundle must not hide a valid same-origin JSON response.
    }
  }
  const path='./data/jolpica/'+Number(year)+'/'+resource+'.json';
  const url=new URL(path,baseUrl).href;
  let snapshotProblem='';
  try {
    const response=await fetcher(url,{cache:refresh?'reload':'default'});
    if (!response.ok) throw new Error('HTTP '+response.status);
    const feed=await response.json();
    if (feed.schema!=='apexium-jolpica-snapshot-v1' || feed.resource!==resource ||
        Number(feed.year)!==Number(year) || !Array.isArray(feed.rows) ||
        feed.rows.some(row=>!row || typeof row!=='object' || Array.isArray(row)) ||
        !feed.fetchedAt || !/^https:\/\/api\.jolpi\.ca\//.test(feed.url)) {
      throw new Error('Formato do snapshot inesperado');
    }
    return {rows:feed.rows,source:'jolpica',url:feed.url,fetchedAt:feed.fetchedAt,
      cached:true,metadata:{...feed.metadata,via:'apexium-pages-snapshot'}};
  } catch(error) {
    snapshotProblem=error instanceof Error?error.message:String(error);
  }
  // Standalone and unsupported historical years may still attempt the direct API.
  try {
    return await api.jolpica.query(resource,{season:Number(year),limit:100,
      ttl:refresh?0:undefined});
  } catch(error) {
    const detail=error instanceof Error?error.message:String(error);
    throw new Error('Dados da temporada '+year+' indisponíveis no site '+
      '(snapshot: '+snapshotProblem+') e na API externa ('+detail+
      '). Consulte o histórico de sincronização do APEXIUM.');
  }
}
